INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Software > Konfiguration und Inbetriebnahme > Betriebssysteme > Linux
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann Linux ohne Anpassung auf jeder Hardware installiert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Hardwarekompatibilität muss geprüft werden"}, {"text": "Ja", "correct": false, "because": "Inkompatibilität möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Konfiguration von Linux immer Treiber manuell installiert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Viele Treiber sind im Kernel enthalten"}, {"text": "Ja", "correct": false, "because": "Nicht immer manuell nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Linux immer als Open-Source-Software verfügbar?', 2, '[{"text": "Ja", "correct": true, "because": "Linux basiert auf Open-Source-Prinzipien"}, {"text": "Nein", "correct": false, "because": "Open Source ist Kernmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Linux-Systeme ohne Kommandozeilenkenntnisse konfiguriert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Grafische Oberflächen verfügbar"}, {"text": "Nein", "correct": false, "because": "GUI erleichtert Konfiguration"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Inbetriebnahme von Linux immer komplexer als bei Windows?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Distribution und Erfahrung"}, {"text": "Ja", "correct": false, "because": "Komplexität variiert"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt ist bei der Inbetriebnahme von Linux am wichtigsten?', 3, '[{"text": "Auswahl der Distribution", "correct": true, "because": "Bestimmt Funktionen und Nutzung"}, {"text": "Farbauswahl", "correct": false, "because": "Ästhetisch, nicht funktional"}, {"text": "Markenwahl", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Linux-Distribution ist für Anfänger besonders geeignet?', 2, '[{"text": "Ubuntu", "correct": true, "because": "Benutzerfreundlich und gut unterstützt"}, {"text": "Arch Linux", "correct": false, "because": "Für Fortgeschrittene"}, {"text": "Debian", "correct": false, "because": "Flexibel, aber komplexer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug wird oft zur Konfiguration von Linux-Systemen verwendet?', 2, '[{"text": "Terminal", "correct": true, "because": "Ermöglicht direkte Befehle"}, {"text": "Texteditor", "correct": false, "because": "Zusätzliches Werkzeug"}, {"text": "Browser", "correct": false, "because": "Nicht primär für Konfiguration"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datei wird häufig zur Netzwerkkonfiguration in Linux bearbeitet?', 3, '[{"text": "/etc/network/interfaces", "correct": true, "because": "Enthält Netzwerkeinstellungen"}, {"text": "/etc/passwd", "correct": false, "because": "Für Benutzer"}, {"text": "/etc/hosts", "correct": false, "because": "Für Hostnamen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil von Linux bei der Konfiguration?', 2, '[{"text": "Hohe Anpassbarkeit", "correct": true, "because": "Flexibel konfigurierbar"}, {"text": "Geringe Kosten", "correct": false, "because": "Zusätzlicher Vorteil"}, {"text": "Schnelle Installation", "correct": false, "because": "Abhängig von Distribution"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei der Inbetriebnahme von Linux typisch?', 4, '[{"text": "Distribution auswählen", "correct": true, "because": "Basis der Installation"}, {"text": "Bootmedium erstellen", "correct": true, "because": "Für Installation nötig"}, {"text": "Partitionierung", "correct": true, "because": "Festplatte einrichten"}, {"text": "Farbschema wählen", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Linux bei der Konfiguration?', 3, '[{"text": "Open Source", "correct": true, "because": "Kostenlos und anpassbar"}, {"text": "Stabilität", "correct": true, "because": "Zuverlässig bei Servern"}, {"text": "Flexibilität", "correct": true, "because": "Viele Konfigurationsoptionen"}, {"text": "Einfache Bedienung", "correct": false, "because": "Komplexität variiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Konfiguration von Linux auftreten?', 3, '[{"text": "Inkompatible Hardware", "correct": true, "because": "Treiber fehlen"}, {"text": "Komplexe Kommandozeile", "correct": true, "because": "Für Anfänger schwierig"}, {"text": "Fehlende Unterstützung", "correct": true, "because": "Kommt auf Distribution an"}, {"text": "Hohe Kosten", "correct": false, "because": "Kostenlos verfügbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten müssen bei der Linux-Konfiguration angepasst werden?', 4, '[{"text": "Kernel", "correct": true, "because": "Steuert Hardware"}, {"text": "Netzwerkeinstellungen", "correct": true, "because": "Für Konnektivität"}, {"text": "Benutzerkonten", "correct": true, "because": "Sicherheit und Zugriff"}, {"text": "Monitorauflösung", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Distributionen sind für Server typisch?', 3, '[{"text": "Ubuntu Server", "correct": true, "because": "Weit verbreitet"}, {"text": "CentOS", "correct": true, "because": "Stabil und unterstützt"}, {"text": "Debian", "correct": true, "because": "Zuverlässig für Server"}, {"text": "Linux Mint", "correct": false, "because": "Desktop-orientiert"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ubuntu ist eine benutzerfreundliche Linux-Distribution. b) Linux erfordert immer manuelle Treiberinstallation.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ubuntu ja, Treiber oft enthalten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Linux ist Open-Source-Software. b) Die Konfiguration ist immer komplexer als bei Windows.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Open Source ja, Komplexität variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Datei /etc/network/interfaces konfiguriert Netzwerke in Linux. b) Linux kann nur über die Kommandozeile konfiguriert werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Netzwerk ja, GUI möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Linux bietet hohe Anpassbarkeit bei der Konfiguration. b) Hardwarekompatibilität ist bei Linux kein Problem.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Anpassbarkeit ja, Kompatibilität variabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) CentOS ist für Server geeignet. b) Linux-Inbetriebnahme erfordert keine Partitionierung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "CentOS ja, Partitionierung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

